// === Tab: mySketch ===
// 🌸 MINDRIC VOID BLOOM
// Hypnotic Generative Mandala
// Vibe Coding: Mindric Lab

let t = 0;

function setup() {
  createCanvas(window.innerWidth, window.innerHeight);
  colorMode(HSB, 360, 100, 100, 100);
  background(0);
}

function draw() {
  // 1. TRAILS EFFEKT
  // Wir übermalen das Bild nicht komplett, sondern nur ganz leicht schwarz.
  // Dadurch entstehen diese geilen "Schlieren" (Motion Blur).
  background(0, 0, 0, 10); // Alpha 10 = sehr lange Trails

  translate(width / 2, height / 2); // Nullpunkt in die Mitte

  // Interaktion holen
  // Maus X = Zoom/Explosion, Maus Y = Farbverschiebung
  let expansion = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 1, 3); 
  let colorShift = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 0, 100);

  noFill();

  // 2. DIE SCHLEIFE DES WAHNSINNS
  // Wir zeichnen 50 Ringe
  for (let i = 0; i < 50; i++) {

    // Dynamische Farbe
    // HUE rotiert mit der Zeit + Ring-Index + Maus
    let hue = (t * 20 + i * 5 + colorShift) % 360;

    stroke(hue, 80, 100);
    strokeWeight(1.5);

    beginShape();
    // Jeder Ring hat eine verzerrte Form
    for (let a = 0; a < TWO_PI; a += 0.05) {

      // Das Herzstück: Die Formel
      // Wir kombinieren Sinus-Wellen für Symmetrie
      let rad = map(sin(a * 8 + t), -1, 1, 50, 150); // Grundform (Blüte)
      let noiseVal = noise(a * 2, i * 0.1, t * 0.5); // Organisches Zittern

      // Radius berechnen
      // i * 5 = Ringe werden größer nach außen
      let r = (rad + (i * 8)) * expansion * noiseVal;

      let x = r * cos(a);
      let y = r * sin(a);

      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // 3. MINIMAL BRANDING (Zentriert & Clean)
  // Wir zeichnen das Branding NACH dem Reset der Matrix, damit es oben links steht
  resetMatrix(); 

  // Kleiner Glitch-Effekt beim Text
  if(random(1) > 0.95) {
      fill(255);
  } else {
      fill(150);
  }
  noStroke();
  textFont('Courier New');
  textSize(14);
  textAlign(LEFT, TOP);
  text("MINDRIC LAB :: VOID BLOOM", 20, 20);

  textSize(10);
  fill(100);
  text("GENERATIVE ART SERIES [P5.JS]", 20, 40);

  // Zeit weiterschalten
  t += 0.005;
}

function windowResized() {
  resizeCanvas(window.innerWidth, window.innerHeight);
  background(0); // Reset bei Resize
}

